#include "ProjectAssets.h"
static int assetSearchProbe(int argc,char** argv){
    if(argc!=5)return 2;File folder(String::fromUTF8(argv[2]));auto hash=String::fromUTF8(argv[3]);auto bytes=String::fromUTF8(argv[4]).getLargeIntValue();if(hash.length()!=64||!hash.containsOnly("0123456789abcdef")||bytes<=0)return 2;
    auto project=emptyProject();project.tracks[0].instrument=Instrument::sample;project.tracks[0].samplePath=folder.getSiblingFile("missing").getChildFile(hash+".wav").getFullPathName();auto rows=projectAssets(project,folder.getParentDirectory());rows[0].contentBytes=bytes;auto message=findProjectAssets(rows,folder);DynamicObject::Ptr result=new DynamicObject();Array<var> candidates;for(const auto& file:rows[0].candidates)candidates.add(file.getFullPathName());result->setProperty("candidates",candidates);result->setProperty("complete",rows[0].searchComplete);result->setProperty("message",message);std::cout<<JSON::toString(var(result),true).toStdString()<<"\n";return 0;
}
static bool fingerprintCoreWave(const File& file,int variant=0){file.getParentDirectory().createDirectory();AudioBuffer<float> audio(2,4800);for(int i=0;i<4800;++i){audio.setSample(0,i,.2f*std::sin((variant+1)*i*.053));audio.setSample(1,i,.15f*std::cos((variant+1)*i*.041));}std::unique_ptr<OutputStream> stream(file.createOutputStream());WavAudioFormat format;auto writer=format.createWriterFor(stream,AudioFormatWriterOptions{}.withSampleRate(48000).withNumChannels(2).withBitsPerSample(24));return writer&&writer->writeFromAudioSampleBuffer(audio,0,4800);}
static void testAssetFingerprints(const File& parent,Assets& assets){
    auto root=parent.getChildFile("fingerprints-"+Uuid().toString());root.createDirectory();auto original=root.getChildFile("original/vault.wav");expect(fingerprintCoreWave(original),"fingerprint fixture writes stereo audio");AssetFingerprint fingerprint;
    expect(fingerprintAssetFile(original,fingerprint).wasOk()&&fingerprint.hash==SHA256(original).toHexString()&&fingerprint.bytes==original.getSize()&&fingerprint.modified==original.getLastModificationTime().toMilliseconds(),"streamed fingerprint matches full SHA-256 with source metadata");
    auto retained=fingerprint;std::atomic<bool> cancel{true};expect(fingerprintAssetFile(original,fingerprint,&cancel).failed()&&fingerprint==retained,"cancelled hashing preserves the caller's previous fingerprint");expect(fingerprintAssetFile(root.getChildFile("absent.wav"),fingerprint).failed()&&fingerprint==retained,"missing fingerprint source fails without changing output");
    auto project=emptyProject();project.songMode=true;project.loop=false;project.tracks[0].instrument=Instrument::sample;project.tracks[0].samplePath=original.getFullPathName();project.tracks[0].sampleStart=.02;project.tracks[0].sampleEnd=.08;project.tracks[0].sampleLoop=true;Clip clip;clip.track=0;clip.audioPath=original.getFullPathName();clip.sourceOffset=.01;clip.length=.1;clip.fadeIn=.02;clip.fadeOut=.03;clip.fadeInCurve=FadeCurve::sCurve;clip.fadeOutCurve=FadeCurve::equalPower;project.clips.push_back(clip);
    auto rows=projectAssets(project,root);inspectProjectAssets(rows,project);AssetFingerprints cache;auto before=JSON::toString(projectToJson(project));expect(learnProjectAssetFingerprints(rows,cache,true).isEmpty()&&cache.size()==1&&rows[0].contentHash==retained.hash&&rows[0].uses.size()==2&&JSON::toString(projectToJson(project))==before,"background learning deduplicates shared references without changing musical data");
    auto file=root.getChildFile("data/asset-fingerprints.json");expect(saveAssetFingerprints(file,cache,"missing").wasOk(),"local fingerprint catalog saves with verified atomic publication");AssetFingerprints loaded;expect(loadAssetFingerprints(file,loaded).wasOk()&&loaded==cache,"fingerprints persist with raw byte size and observation dates");auto token=assetFingerprintToken(file);auto stableBytes=file.loadFileAsString();expect(saveAssetFingerprints(file,cache,"stale").failed()&&file.loadFileAsString()==stableBytes,"stale catalog token never replaces the current catalog");expect(saveAssetFingerprints(file,cache,token,&cancel).failed()&&file.loadFileAsString()==stableBytes,"cancelled catalog publication retains existing bytes");
    auto library=root.getChildFile("library");library.createDirectory();auto renamed=library.getChildFile("renamed-drone.wav");expect(original.moveFileTo(renamed),"test moves only its isolated audio fixture");rows=projectAssets(project,root);inspectProjectAssets(rows,project);learnProjectAssetFingerprints(rows,loaded,false);expect(rows[0].issue==AssetIssue::missing&&rows[0].contentHash==retained.hash&&rows[0].contentBytes==retained.bytes,"a missing ordinary filename inherits its remembered original identity");
    auto message=findProjectAssets(rows,library);expect(rows[0].searchComplete&&rows[0].candidates==std::vector<File>{renamed}&&message.startsWith("1 unique")&&message.contains("1 content"),"renamed audio is found by exact bytes rather than its old filename");
    auto wrong=library.getChildFile("vault.wav");fingerprintCoreWave(wrong,2);findProjectAssets(rows,library);expect(rows[0].candidates==std::vector<File>{renamed},"same-name different audio cannot displace a content-verified match");auto repaired=project;int references=0;expect(relinkProjectAssets(repaired,root,{{rows[0].key,renamed,rows[0].contentHash}},&references).wasOk()&&references==2&&repaired.tracks[0].samplePath==renamed.getFullPathName()&&repaired.clips[0].audioPath==renamed.getFullPathName(),"content repair updates every shared sampler/Playlist reference atomically");
    expect(repaired.tracks[0].sampleStart==.02&&repaired.tracks[0].sampleEnd==.08&&repaired.tracks[0].sampleLoop&&repaired.clips[0].sourceOffset==.01&&repaired.clips[0].fadeInCurve==FadeCurve::sCurve&&repaired.clips[0].fadeOutCurve==FadeCurve::equalPower,"recovery retains sampler selections and independent audio fade shapes");auto audio=render(repaired,assets,root,2400);expect(audio.getMagnitude(0,0,2400)>.001f,"repaired source produces callback audio");
    repaired=project;expect(relinkProjectAssets(repaired,root,{{rows[0].key,wrong,rows[0].contentHash}}).failed()&&JSON::toString(projectToJson(repaired))==before,"changed candidate bytes reject without modifying any shared references");
    auto duplicate=library.getChildFile("copy.wav");renamed.copyFileTo(duplicate);findProjectAssets(rows,library);expect(rows[0].candidates.size()==2&&rows[0].searchComplete,"identical copies remain ambiguous and need explicit choice");
    auto hashed=project;hashed.tracks[0].samplePath=root.getChildFile("missing/"+retained.hash+".wav").getFullPathName();hashed.clips.clear();auto hashedRows=projectAssets(hashed,root);inspectProjectAssets(hashedRows,hashed);findProjectAssets(hashedRows,library);expect(hashedRows[0].contentBytes==0&&hashedRows[0].candidates.size()==2,"collected SHA-256 names recover renamed supported audio without a local catalog");
    auto limited=root.getChildFile("limited");limited.createDirectory();renamed.copyFileTo(limited.getChildFile("a.wav"));renamed.copyFileTo(limited.getChildFile("b.wav"));AssetSearchLimits limits;limits.entries=1;message=findProjectAssets(rows,limited,nullptr,limits);expect(!rows[0].searchComplete&&rows[0].candidates.size()==1&&message.startsWith("0 unique"),"entry-limited scans never present a partial single match as unique");limits={};limits.hashBytes=renamed.getSize();message=findProjectAssets(rows,limited,nullptr,limits);expect(!rows[0].searchComplete&&rows[0].candidates.size()==1&&message.contains("Content read limit"),"hash-byte budgets retain explicit proposals but disable automatic unique matching");
    message=findProjectAssets(rows,library,&cancel);expect(message.contains("cancelled")&&rows[0].candidates.empty()&&!rows[0].searchComplete,"cancelled search discards all partial proposals");limits.entries=0;expect(findProjectAssets(rows,library,nullptr,limits).contains("Invalid")&&!rows[0].searchComplete,"invalid search limits publish no complete result");
    auto unobserved=project;unobserved.tracks[0].samplePath=root.getChildFile("missing/vault.wav").getFullPathName();unobserved.clips.clear();auto unknownRows=projectAssets(unobserved,root);inspectProjectAssets(unknownRows,unobserved);findProjectAssets(unknownRows,library);expect(unknownRows[0].contentHash.isEmpty()&&unknownRows[0].candidates==std::vector<File>{wrong}&&unknownRows[0].searchComplete,"unobserved ordinary paths retain explicitly identifiable filename-only fallback");
    auto many=root.getChildFile("many");many.createDirectory();for(int i=0;i<18;++i)renamed.copyFileTo(many.getChildFile(String(i)+".wav"));findProjectAssets(rows,many);expect(rows[0].candidates.size()==16&&rows[0].candidatesLimited&&rows[0].searchComplete,"candidate lists cap at sixteen without disguising additional identical copies");
    auto corrupted=library.getChildFile(retained.hash+".wav");wrong.copyFileTo(corrupted);auto damaged=hashed;damaged.tracks[0].samplePath=corrupted.getFullPathName();auto damagedRows=projectAssets(damaged,root);inspectProjectAssets(damagedRows,damaged);AssetFingerprints scratch;learnProjectAssetFingerprints(damagedRows,scratch,true);expect(damagedRows[0].issue==AssetIssue::checksumMismatch&&scratch.empty(),"an existing collected file with wrong bytes is flagged and cannot redefine its identity");
    auto invalidRange=project;invalidRange.tracks[0].sampleEnd=1;expect(relinkProjectAssets(invalidRange,root,{{rows[0].key,renamed,retained.hash}}).failed()&&invalidRange.tracks[0].samplePath==project.tracks[0].samplePath,"exact byte matches still respect saved sampler range validation");
    auto source=emptyProject();source.tracks[0].instrument=Instrument::sample;source.tracks[0].samplePath=renamed.getFullPathName();auto fresh=projectAssets(source,root);inspectProjectAssets(fresh,source);scratch.clear();auto warning=learnProjectAssetFingerprints(fresh,scratch,true,nullptr,0);expect(scratch.empty()&&warning.contains("not fingerprinted"),"learning budgets warn while leaving musical audio usable");
    scratch=cache;auto repeated=projectAssets(source,root);inspectProjectAssets(repeated,source);learnProjectAssetFingerprints(repeated,scratch,true);expect(scratch.size()==2,"a renamed present file can be observed independently while retaining its old missing path identity");
    auto stable=loaded;for(int bad=0;bad<7;++bad){auto broken=JSON::parse(stableBytes);auto* item=(*broken["sources"].getArray())[0].getDynamicObject();if(bad==0)item->setProperty("sha256","bad");if(bad==1)item->setProperty("bytes",true);if(bad==2)item->setProperty("bytes",maxFingerprintFileBytes+1);if(bad==3)item->setProperty("path","relative.wav");if(bad==4)item->setProperty("modified",-1);if(bad==5)broken.getDynamicObject()->setProperty("schema",2);if(bad==6)broken["sources"].getArray()->add((*broken["sources"].getArray())[0]);file.replaceWithText(JSON::toString(broken));expect(loadAssetFingerprints(file,loaded).failed()&&loaded==stable,"invalid cache record schema/hash/type/path/range/duplicate preserves previous observations");}
    file.replaceWithText("{broken");expect(loadAssetFingerprints(file,loaded).failed()&&loaded==stable&&file.loadFileAsString()=="{broken","corrupt fingerprint catalogs are retained rather than silently rebuilt");
    AssetFingerprints large;for(int i=0;i<1030;++i){auto old=retained;old.path=root.getChildFile("past/"+String(i)+".wav").getFullPathName();old.seen=0;large.push_back(old);}fresh=projectAssets(source,root);inspectProjectAssets(fresh,source);learnProjectAssetFingerprints(fresh,large,true);expect(large.size()==1024&&large.front().path==renamed.getFullPathName(),"bounded fingerprint catalog evicts oldest observations while keeping current sources");
    expect(JSON::toString(projectToJson(project))==before,"fingerprint cache and recovery search do not change the project schema or song");
    auto pair=source;pair.tracks[1].instrument=Instrument::sample;pair.tracks[1].samplePath=duplicate.getFullPathName();auto pairRows=projectAssets(pair,root);inspectProjectAssets(pairRows,pair);AssetFingerprints incremental;learnProjectAssetFingerprints(pairRows,incremental,true,nullptr,renamed.getSize());expect(incremental.size()==1,"a small learning pass observes only files within its byte budget");learnProjectAssetFingerprints(pairRows,incremental,true,nullptr,renamed.getSize());expect(incremental.size()==2,"subsequent bounded refresh prioritizes previously unobserved sources instead of rehashing the same first file forever");
}
